def word_frequency(text: str) -> dict[str, int]:
    punctuation = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
    counts: dict[str, int] = {}
    for word in text.split():
        word = word.strip(punctuation).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
